query PrChecksQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      headRefOid
      commits(last: 1) {
        nodes {
          commit {
            oid
            statusCheckRollup {
              contexts(first: 100) {
                totalCount
                pageInfo {
                  hasNextPage
                  endCursor
                }
                nodes {
                  __typename
                  ... on CheckRun {
                    name
                    status
                    conclusion
                    startedAt
                    completedAt
                    title
                    detailsUrl
                    checkSuite {
                      app {
                        name
                      }
                      workflowRun {
                        workflow {
                          name
                        }
                      }
                    }
                    annotations(first: 50) {
                      totalCount
                      nodes {
                        path
                        blobUrl
                        location {
                          start {
                            line
                          }
                          end {
                            line
                          }
                        }
                        annotationLevel
                        title
                        message
                      }
                    }
                  }
                  ... on StatusContext {
                    context
                    state
                    description
                    targetUrl
                    createdAt
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
